command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/transfer-item-budget-20261006"
$baseline="4f03ea8bc499cd8e4d064431753d4f7aefac0fff"
$candidate="36f4f400239beac526a5bf273c51a81000701642"
$temp=Join-Path $env:RUNNER_TEMP ("transfer-budget-gui-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --no-tags --prune
  if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
  $mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
  $branchSha=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($mainSha -ne $baseline){throw "main moved before transfer-budget GUI validation: $mainSha"}
  if($branchSha -ne $candidate){throw "candidate moved before transfer-budget GUI validation: $branchSha"}

  & git diff --quiet d4770a2a3c16698172a2e169201f7d5f79326875 $candidate -- app src tests/winui/m22 tests/winui/m23 tests/winui/test_file_operation_controller_contract.py tests/winui/test_localization_contract.py tests/winui/test_transfer_budget_contract.py
  if($LASTEXITCODE -ne 0){throw "product/native/source-contract files changed after #459"}

  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & git diff --check $baseline $candidate
  if($LASTEXITCODE -ne 0){throw "git diff --check failed"}

  & python -X utf8 tools\winui\check_python_static.py tests\winui\test_transfer_budget_gui.py
  if($LASTEXITCODE -ne 0){throw "transfer-budget GUI Python static check failed"}

  & python -X utf8 tools\winui\run_checks.py fast --before $baseline --head $candidate
  if($LASTEXITCODE -ne 0){throw "FAST validation failed"}

  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "Release build failed"}

  $env:FLY_MIGRATION_CONFIGURATION="Release"
  & python -X utf8 -u tests\winui\test_transfer_budget_gui.py
  if($LASTEXITCODE -ne 0){throw "64-item focused transfer GUI failed"}

  Write-Host ("TRANSFER_BUDGET_GUI_CANDIDATE="+$candidate)
  Write-Host "TRANSFER_BUDGET_GUI_ACCEPTANCE=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
